mapper.select:
SELECT id, member_id, jeongmo_id, name, birth_date, jeongmo_date, jeongmo_start_time, jeongmo_end_time, jeongmo_place, reg_dtm, chg_dtm FROM attendance_records
AND jeongmo_date = #{jeongmoDate}
AND jeongmo_start_time = #{jeongmoStartTime}
AND jeongmo_end_time = #{jeongmoEndTime}
AND UPPER(jeongmo_place) = UPPER(#{jeongmoPlace})
ORDER BY reg_dtm ASC, id ASC

mapper.update:
UPDATE attendance_records
SET jeongmo_id = #{jeongmoId},
    chg_dtm = CURRENT_TIMESTAMP
WHERE jeongmo_id IS NULL
  AND jeongmo_date = #{jeongmoDate}
  AND jeongmo_start_time = #{jeongmoStartTime}
  AND jeongmo_end_time = #{jeongmoEndTime}
  AND jeongmo_place = #{jeongmoPlace}
